// Responsive variants of the product photos (generated by a one-off script).
// Use with the product's normal `image` as src: <img src={p.image} {...productImgProps(p.id)} />
import admixtures512 from "@/assets/product-admixtures-512w.webp";
import admixtures768 from "@/assets/product-admixtures-768w.webp";
import admixturesFull from "@/assets/product-admixtures.webp";
import waterproofing512 from "@/assets/product-waterproofing-512w.webp";
import waterproofing768 from "@/assets/product-waterproofing-768w.webp";
import waterproofingFull from "@/assets/product-waterproofing.webp";
import puInjection512 from "@/assets/product-pu-injection-512w.webp";
import puInjection768 from "@/assets/product-pu-injection-768w.webp";
import puInjectionFull from "@/assets/product-pu-injection.webp";
import nonshrinkGrout512 from "@/assets/product-nonshrink-grout-512w.webp";
import nonshrinkGroutFull from "@/assets/product-nonshrink-grout.webp";
import epoxyGrout512 from "@/assets/product-epoxy-grout-512w.webp";
import epoxyGrout768 from "@/assets/product-epoxy-grout-768w.webp";
import epoxyGroutFull from "@/assets/product-epoxy-grout.webp";
import protectiveCoatings512 from "@/assets/product-protective-coatings-512w.webp";
import protectiveCoatings768 from "@/assets/product-protective-coatings-768w.webp";
import protectiveCoatingsFull from "@/assets/product-protective-coatings.webp";
import concreteRepair512 from "@/assets/product-concrete-repair-512w.webp";
import concreteRepair768 from "@/assets/product-concrete-repair-768w.webp";
import concreteRepairFull from "@/assets/product-concrete-repair.webp";
import microconcrete512 from "@/assets/product-microconcrete-512w.webp";
import microconcrete768 from "@/assets/product-microconcrete-768w.webp";
import microconcreteFull from "@/assets/product-microconcrete.webp";

const productImages: Record<string, { srcSet: string; width: number; height: number }> = {
  "concrete-admixtures": { srcSet: `${admixtures512} 512w, ${admixtures768} 768w, ${admixturesFull} 1024w`, width: 1024, height: 682 },
  "waterproofing-chemicals": { srcSet: `${waterproofing512} 512w, ${waterproofing768} 768w, ${waterproofingFull} 1024w`, width: 1024, height: 683 },
  "pu-injection-grouting": { srcSet: `${puInjection512} 512w, ${puInjection768} 768w, ${puInjectionFull} 1024w`, width: 1024, height: 768 },
  "non-shrink-grout": { srcSet: `${nonshrinkGrout512} 512w, ${nonshrinkGroutFull} 768w`, width: 768, height: 482 },
  "epoxy-grouting": { srcSet: `${epoxyGrout512} 512w, ${epoxyGrout768} 768w, ${epoxyGroutFull} 1024w`, width: 1024, height: 682 },
  "protective-coatings": { srcSet: `${protectiveCoatings512} 512w, ${protectiveCoatings768} 768w, ${protectiveCoatingsFull} 1024w`, width: 1024, height: 767 },
  "concrete-repair": { srcSet: `${concreteRepair512} 512w, ${concreteRepair768} 768w, ${concreteRepairFull} 1024w`, width: 1024, height: 558 },
  "micro-concrete": { srcSet: `${microconcrete512} 512w, ${microconcrete768} 768w, ${microconcreteFull} 1024w`, width: 1024, height: 683 },
};

/** Card images: full width on phones, 2 columns on tablets, 3-4 columns on desktop. */
export const PRODUCT_CARD_SIZES = "(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw";

export function productImgProps(id: string, sizes: string = PRODUCT_CARD_SIZES) {
  const v = productImages[id];
  return v ? { srcSet: v.srcSet, sizes, width: v.width, height: v.height } : {};
}
